const V=(l,d)=>({type:"color",value:[{value:l,theme:{mode:"light"}},{value:d,theme:{mode:"dark"}}]});
const F="Geist";
function fr(p,name,o={}){return Insert(p,{type:"frame",name,...o});}
function tx(p,c,o={}){return Insert(p,{type:"text",name:o.name||("Text "+String(c).slice(0,24)),content:String(c),fontFamily:F,fontSize:13,fill:"$fg",...o});}
function ic(p,icon,o={}){return Insert(p,{type:"icon",name:"Icon "+icon,library:"lucide",icon,width:16,height:16,fill:"$muted-fg",...o});}
function sp(p){return fr(p,"Spacer",{width:"fill_container",height:1});}
function vsp(p){return fr(p,"Spacer",{width:1,height:"fill_container"});}
function badge(p,label,kind="neutral"){const m={neutral:["$muted","$muted-fg"],success:["$success-bg","$success"],warn:["$warn-bg","$warn"],info:["$info-bg","$info"],outline:["$bg","$muted-fg"]}[kind];const b=fr(p,"Badge "+label,{padding:[2,8],cornerRadius:999,fill:m[0],alignItems:"center",...(kind=="outline"?{stroke:"$border",strokeWidth:1}:{})});tx(b,label,{fontSize:11,fontWeight:"500",fill:m[1]});return b;}
function btn(p,label,o={}){const kind=o.kind||"outline";const st={primary:{fill:"$primary",c:"$primary-fg"},outline:{fill:"$bg",stroke:"$border",c:"$fg"},ghost:{c:"$fg"}}[kind];const b=fr(p,"Button "+(label||o.icon),{padding:[0,label?12:8],height:32,gap:6,cornerRadius:6,alignItems:"center",justifyContent:"center",...(st.fill?{fill:st.fill}:{}),...(st.stroke?{stroke:st.stroke,strokeWidth:1}:{})});if(o.icon)ic(b,o.icon,{width:14,height:14,fill:st.c});if(label)tx(b,label,{fontWeight:"500",fill:st.c});if(o.count){const c=fr(b,"Count",{padding:[0,6],height:18,cornerRadius:999,fill:kind=="primary"?"$primary-fg":"$muted",alignItems:"center"});tx(c,String(o.count),{fontSize:11,fontWeight:"600",fill:kind=="primary"?"$primary":"$fg"});}return b;}
function nav(p,icon,label,o={}){const r=fr(p,"Nav "+label,{width:"fill_container",height:30,gap:8,padding:[0,8],cornerRadius:6,alignItems:"center",...(o.active?{fill:"$accent"}:{}),...(o.indent?{padding:[0,8,0,8+o.indent]}:{})});ic(r,icon,{width:15,height:15,fill:o.active?"$fg":"$muted-fg"});tx(r,label,{fill:o.active?"$fg":"$muted-fg",fontWeight:o.active?"500":"400"});if(o.badge!==undefined||o.tag)sp(r);if(o.badge!==undefined)tx(r,String(o.badge),{fontSize:12,fill:"$muted-fg"});if(o.tag)badge(r,o.tag,o.tagKind||"neutral");return r;}
function section(p,label,o={}){const s=fr(p,"Section "+label,{layout:"vertical",width:"fill_container",gap:1});const h=fr(s,"Heading",{width:"fill_container",padding:[10,8,4,8],alignItems:"center",gap:6});tx(h,label,{fontSize:11,fontWeight:"500",fill:"$muted-fg",letterSpacing:0.3});if(o.tag){sp(h);badge(h,o.tag,"outline");}return s;}
function avatar(p,initials,o={}){const s=o.size||28;const a=fr(p,"Avatar "+initials,{width:s,height:s,cornerRadius:o.square?Math.round(s/4):999,fill:o.fill||"$brand",alignItems:"center",justifyContent:"center",...(o.ring?{stroke:"$fg",strokeWidth:2,strokeAlignment:"outer"}:{})});tx(a,initials,{fontSize:o.fs||11,fontWeight:"600",fill:"#FFFFFF"});return a;}
function hr(p){return fr(p,"Divider",{width:"fill_container",height:1,fill:"$border"});}
function input(p,ph,o={}){const f=fr(p,"Input "+ph,{width:o.width||"fill_container",height:32,padding:[0,10],gap:8,cornerRadius:6,stroke:"$border",strokeWidth:1,fill:"$bg",alignItems:"center"});if(o.icon)ic(f,o.icon,{width:14,height:14});tx(f,ph,{fill:o.value?"$fg":"$muted-fg"});if(o.kbd||o.trail)sp(f);if(o.kbd){const k=fr(f,"Kbd",{padding:[1,5],cornerRadius:4,stroke:"$border",strokeWidth:1});tx(k,o.kbd,{fontSize:10,fill:"$muted-fg"});}if(o.trail)ic(f,o.trail,{width:14,height:14});return f;}
function field(p,label,val,o={}){const g=fr(p,"Field "+label,{layout:"vertical",gap:6,width:o.width||"fill_container"});tx(g,label,{fontWeight:"500"});input(g,val,{value:!o.ph,trail:o.trail});if(o.hint)tx(g,o.hint,{fontSize:12,fill:"$muted-fg"});return g;}
function check(p,on){const c=fr(p,"Checkbox",{width:16,height:16,cornerRadius:4,alignItems:"center",justifyContent:"center",...(on?{fill:"$primary"}:{stroke:"$border",strokeWidth:1,fill:"$bg"})});if(on)ic(c,"check",{width:12,height:12,fill:"$primary-fg"});return c;}
function toggle(p,on){const t=fr(p,"Switch",{width:36,height:20,cornerRadius:999,padding:2,fill:on?"$primary":"$muted",justifyContent:on?"end":"start"});Insert(t,{type:"ellipse",name:"Knob",width:16,height:16,fill:on?"$primary-fg":"$bg"});return t;}
function card(p,title,desc,o={}){const c=fr(p,"Card "+title,{layout:"vertical",width:"fill_container",cornerRadius:10,stroke:"$border",strokeWidth:1,fill:"$bg",clip:true});const h=fr(c,"Card header",{width:"fill_container",padding:[16,20],gap:12,alignItems:"center"});const t=fr(h,"Titles",{layout:"vertical",gap:2,width:"fill_container"});tx(t,title,{fontSize:15,fontWeight:"600"});if(desc)tx(t,desc,{fill:"$muted-fg",textGrowth:"fixed-width",width:"fill_container",lineHeight:1.45});const b=fr(c,"Card body",{layout:"vertical",width:"fill_container",padding:[0,20,20,20],gap:12});return {c,h,b};}
function screen(name,x,y,o={}){return Insert(document,{type:"frame",name,x,y,width:o.w||1440,height:o.h||900,fill:o.fill||"$bg",clip:true,theme:{mode:o.dark?"dark":"light"},layout:o.layout||"horizontal"});}
function crumbs(p,items){const c=fr(p,"Breadcrumbs",{gap:8,alignItems:"center"});items.forEach((t,i)=>{if(i)tx(c,"/",{fill:"$border",fontSize:14});tx(c,t,{fill:i==items.length-1?"$fg":"$muted-fg",fontWeight:i==items.length-1?"500":"400"});});return c;}
function topbarA(m,items,o={}){const t=fr(m,"Top bar",{width:"fill_container",height:52,padding:[0,16,0,20],alignItems:"center",gap:8,stroke:"$border",strokeWidth:{bottom:1}});ic(t,"panel-left",{});crumbs(t,items);sp(t);if(o.site!==false){btn(t,"Staging",{kind:"ghost",icon:"eye"});btn(t,"Edit on site",{icon:"mouse-pointer-click"});btn(t,"Publish all",{kind:"primary",icon:"upload",count:5});}return t;}
function mainCol(root){return fr(root,"Main",{layout:"vertical",width:"fill_container",height:"fill_container"});}
