function sidebarA(root,o){const sb=fr(root,"Sidebar",{layout:"vertical",width:256,height:"fill_container",fill:"$sidebar",stroke:"$border",strokeWidth:{right:1},padding:12,gap:10});
 const sw=fr(sb,"Context switcher",{width:"fill_container",padding:8,gap:10,cornerRadius:8,alignItems:"center",stroke:"$border",strokeWidth:1,fill:"$bg"});avatar(sw,o.av,{square:true,size:32,fill:o.avFill,fs:12});const col=fr(sw,"Names",{layout:"vertical",gap:1,width:"fill_container"});tx(col,o.title,{fontWeight:"600"});tx(col,o.subtitle,{fontSize:12,fill:"$muted-fg"});ic(sw,"chevrons-up-down",{width:14,height:14});
 input(sb,"Search",{icon:"search",kbd:"⌘K"});
 const navs=fr(sb,"Navigation",{layout:"vertical",width:"fill_container",gap:4});
 for(const s of o.sections){const S=section(navs,s.label,{tag:s.tag});for(const [i,l,op] of s.items)nav(S,i,l,{...(op||{}),active:l==o.active});}
 vsp(sb);
 for(const [i,l] of (o.footer||[]))nav(sb,i,l,{active:l==o.active});
 hr(sb);const u=fr(sb,"User",{width:"fill_container",gap:10,alignItems:"center",padding:[4,4]});avatar(u,"DD",{fill:"#0EA5E9"});const uc=fr(u,"Who",{layout:"vertical",gap:1,width:"fill_container"});tx(uc,"Davide Del Gatto",{fontWeight:"500"});tx(uc,o.role||"Staff · Northwind Studio",{fontSize:12,fill:"$muted-fg"});ic(u,"sun-moon",{});
 return sb;}
const SITE_A=act=>({av:"AB",avFill:"#D97706",title:"Acme Bakery",subtitle:"Acme Ltd · acmebakery.ie",sections:SITE_SECTIONS(),footer:[["settings","Site settings"]],active:act});
function langChip(p,l,s){const m={done:{stroke:"$border",c:"$fg"},review:{fill:"$warn-bg",c:"$warn"},missing:{stroke:"$border",c:"$muted-fg",op:0.45}}[s];const c=fr(p,"Lang "+l,{width:26,height:18,cornerRadius:4,alignItems:"center",justifyContent:"center",...(m.fill?{fill:m.fill}:{}),...(m.stroke?{stroke:m.stroke,strokeWidth:1}:{}),...(m.op?{opacity:m.op}:{})});tx(c,l,{fontSize:10,fontWeight:"600",fill:m.c});return c;}
